import{_ as i,o as a,c as o,j as e,a as n,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/import-export-statistik/verwaltung-export-1-verlauf.png",l="/bilder/import-export-statistik/verwaltung-export-2-pfeile.png",d="/bilder/import-export-statistik/verwaltung-export-3-zeugnisdaten.png",u="/bilder/import-export-statistik/verwaltung-export-4-export-optionen.png",p="/bilder/import-export-statistik/verwaltung-export-5-export-vorlage-speichern.png",g="/bilder/import-export-statistik/verwaltung-export-6-export-word-serienbrief.png",c="/bilder/import-export-statistik/verwaltung-export-7-export-word-serienbrief-word-serienbrief.png",S=JSON.parse('{"title":"Daten als Excel-, Text- oder CSV-Datei exportieren","description":"","frontmatter":{"title":"Daten als Excel-, Text- oder CSV-Datei exportieren","source_pageid":464,"source_revision":6881},"headers":[],"relativePath":"schild3/import-export-statistik/datenexport-im-xlsx-oder-txt-format-tutorial.md","filePath":"schild3/import-export-statistik/datenexport-im-xlsx-oder-txt-format-tutorial.md"}'),h={name:"schild3/import-export-statistik/datenexport-im-xlsx-oder-txt-format-tutorial.md"};function m(x,t,f,b,w,k){return a(),o("div",null,[...t[0]||(t[0]=[e("h1",{id:"daten-als-excel-text-oder-csv-datei-exportieren",tabindex:"-1"},[n("Daten als Excel-, Text- oder CSV-Datei exportieren "),e("a",{class:"header-anchor",href:"#daten-als-excel-text-oder-csv-datei-exportieren","aria-label":'Permalink to "Daten als Excel-, Text- oder CSV-Datei exportieren"'},"​")],-1),e("p",null,"Wählen Sie Datenart und Felder für einen individuellen Export. Vorlagen und Feldzuordnungen unterstützen wiederkehrende Ausgaben und den Seriendruck in Word.",-1),e("p",null,"Aus SchILD können viele Daten exportiert werden, so dass diese in Excel oder als Textdatei von weiteren Programmen verarbeitet werden können.",-1),e("p",null,[n("Es lässt sich auch eine "),e("em",null,"Feldzuordnungsdatei"),n(" festlegen, um direkt Formate zu erzeugen, die von anderen Programmen erwartet werden.")],-1),e("h2",{id:"videotutorial-zum-datenexport-im-xlsx-oder-txt-format",tabindex:"-1"},[n("Videotutorial zum Datenexport im xlsx- oder txt-Format "),e("a",{class:"header-anchor",href:"#videotutorial-zum-datenexport-im-xlsx-oder-txt-format","aria-label":'Permalink to "Videotutorial zum Datenexport im xlsx- oder txt-Format"'},"​")],-1),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/NNczZmza6J4?",frameborder:"0",allowfullscreen:""},null,-1),r('<h2 id="daten-nach-excel-oder-als-csv-exportieren" tabindex="-1">Daten nach Excel oder als CSV exportieren <a class="header-anchor" href="#daten-nach-excel-oder-als-csv-exportieren" aria-label="Permalink to &quot;Daten nach Excel oder als CSV exportieren&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/verwaltung-export-1-verlauf.png"><img src="'+s+'" alt="Der Verlauf des Exports." loading="lazy"></a></p><p><em>Der Verlauf des Exports.</em></p><p><a href="/bilder/import-export-statistik/verwaltung-export-2-pfeile.png"><img src="'+l+'" alt="Verändern der Felderreihenfolge." loading="lazy"></a></p><p><em>Verändern der Felderreihenfolge.</em></p><p>Der Weg des Exports für Tabellenkalkulationsprogramme wie MS Excel oder Open Office Calc wird wie im Screenshot gezeigt durchgeführt.</p><p>Der Export verläuft, sofern keine besonderen Ziele verfolgt werden, nach dieser Liste:</p><ol><li><strong>Auswahl der Schüler</strong>: Soll nicht der komplette Schülerbestand exportiert werden, wird zuerst im Reiter <em>Schüler</em> auf die gewünschten Personen gefiltert.</li><li><strong>Öffnen des Export-Werkzeugs</strong>: Über <em>Verwaltung ➜ Export ➜ Als Excel-/Textdateien.</em></li><li><strong>Datenart wählen</strong>: Es stehen die Datenarten <em>Schüler</em>, <em>Lehrer</em>, <em>Erziehungsberechtigte</em>, <em>Telefonische Ansprechpartner</em> und <em>Allgemeine Adressen</em> zur Verfügung.</li><li><strong>Felder auswählen:</strong> Übernehmen Sie die benötigten Datenfelder mit einem Doppelklick oder dem kleinen Pfeil oben rechts in die Auswahl. Auf dieselbe Weise entfernen Sie Felder wieder. Ordnen Sie die ausgewählten Felder mit den roten Pfeilen unterhalb der Liste. Die Reihenfolge von oben nach unten entspricht später den Spalten von links nach rechts. Für die Datenart <strong>Schüler</strong> steht zusätzlich der Reiter <strong>Zeugnisdaten</strong> zur Verfügung; siehe den Abschnitt weiter unten.</li><li><strong>Ausgabedatei</strong>: Hier werden Speicherort und Name der Ausgabedatei gewählt. Soll die Datei direkt in Excel geöffnet werden, ist im Dropdown-Menü die Endung <em>.xlsx</em> zu wählen, ansonsten <em>.txt</em>. Über <em>*.*</em> lassen sich beliebige Dateiendungen vergeben (z.B. &quot;Export.csv&quot;, &quot;daten_2023.dat&quot; usw.).</li><li><strong>Export starten</strong>: Startet den Export.</li></ol><h3 id="zeugnisdaten" tabindex="-1">Zeugnisdaten <a class="header-anchor" href="#zeugnisdaten" aria-label="Permalink to &quot;Zeugnisdaten&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/verwaltung-export-3-zeugnisdaten.png"><img src="'+d+'" alt="Ausgabe von Zeugnisdaten in der Datenart Schüler." loading="lazy"></a></p><p><em>Ausgabe von Zeugnisdaten in der Datenart Schüler.</em></p><p>Sollen mit der Leistung verbundene Daten exportiert werden, ist in der Datenart <em>Schüler</em> der Reiter <em>Zeugnisdaten</em> anzuwählen.</p><p>Dort wird der Haken bei <strong>Zeugnisdaten exportieren</strong> gesetzt.</p><p>Weiterhin ist das passende <strong>Halbjahr</strong> auszuwählen. Somit lassen sich auch Leistungsdaten für vergangene Lernabschnitte exportieren.</p><p>Im Feld <em>Fächer</em> lässt sich konfigurieren, in welchem Format Noten ausgegeben werden, also als Zahlen, Klartext oder auch als Klartext mit Tendenz. Für die gymnasiale Oberstufe können Noten als Punkte exportiert werden.</p><p>Die Fächer sind als Standardeinstellung auf die beschränkt, die als Zeugnisfach gekennzeichnet sind. Über den Haken oben können auch alle Fächer zur Wahl gestellt werden.</p><p>In den folgenden drei Feldern sind nun neben den konkreten ausgegebenen <em>Fächern</em> auch weitere Informationen rund um Leistungsdaten zugänglich, etwa die zu einer Note gehörende <em>Kursart</em>.</p><h3 id="export-optionen" tabindex="-1">Export-Optionen <a class="header-anchor" href="#export-optionen" aria-label="Permalink to &quot;Export-Optionen&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/verwaltung-export-4-export-optionen.png"><img src="'+u+'" alt="Konfigurationsoptionen für den Export." loading="lazy"></a></p><p><em>Konfigurationsoptionen für den Export.</em></p><ul><li><strong>Feld-Trennzeichen</strong>: Dieses Zeichen trennt die unterschiedlichen Datenfelder. Um lediglich eine Excel-Tabelle oder eine generische .csv-Datei zu erstellen, kann das Standard-Semikolon belassen werden. Ansonsten kann das Zeichen gewählt werden, das von einem zur Weiterverarbeitung bestimmten Programm erwartet wird. Die SchILD-Schnittstellendateien zum Beispiel nutzen das Zeichen <strong>|</strong>.</li><li><strong>Begrenzer f. Textfelder</strong>: Felder, die als Daten &quot;Text&quot; enthalten, zum Beispiel in Abgrenzung zu Zahlen, sind von diesem Zeichen eingeschlossen. Hier kann wieder der Standard belassen werden, sollte ein anderes Programm ein anderes Zeichen nutzen, wäre dies hier direkt beim Export zu wählen.</li><li><strong>Ausgabewert für logisches &quot;Ja&quot;/&quot;Nein&quot;</strong>: Sollen logische Werte verarbeitet werden, lässt sich deren Codierung hierüber festlegen.</li><li><strong>Ausgabewert für &quot;weiblich&quot;/&quot;männlich&quot;</strong>: Wie oben, nur in Bezug auf das Geschlecht.</li><li><strong>Datumsformat</strong>: Hier kann das Format für Datumsangaben gewählt werden, das für den beabsichtigten Zweck am sinnvollsten ist.</li><li><strong>Datum mit Textbegrenzern ausgeben</strong>: Als Standard wird das Datum ohne die <em>Begrenzer für Textfelder</em> erzeugt. Beispielsweise kann MS Excel Datumswerte direkt verarbeiten, andere Programme könnten Datumswerte wie andere Felder als Text erwarten, der dann auch in die Begrenzer einzufassen wäre.</li><li><strong>Kopfzeile ausgeben</strong>: Ist der Haken gesetzt, handelt es sich bei der ersten Zeile in der Exportdatei um die Namen der Datenfelder. Bei einer Abwahl des Hakens beginnt die Datei mit der ersten Datenzeile.</li></ul><h3 id="vorlagen-speichern-und-laden" tabindex="-1">Vorlagen speichern und laden <a class="header-anchor" href="#vorlagen-speichern-und-laden" aria-label="Permalink to &quot;Vorlagen speichern und laden&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/verwaltung-export-5-export-vorlage-speichern.png"><img src="'+p+'" alt="Speichern von Export-Einstellungen als Vorlage." loading="lazy"></a></p><p><em>Speichern von Export-Einstellungen als Vorlage.</em></p><p>Wurde für einen Zweck ein passender Export eingestellt, können alle diese Einstellungen zur erneuten Verwendung gespeichert und später neu geladen werden.</p><p>Klicken Sie hierzu auf <strong>Als Vorlage speichern</strong>.</p><p>Wie in SchILD üblich kann nun eine neue Zeile mit einem Klick auf das <strong>+</strong> angelegt und benannt werden. Geben Sie einen sprechenden Namen, im Screenshot sind einige vielleicht nützliche Beispiele zu sehen.</p><p>Klicken Sie dann auf <strong>Übernehmen</strong>, um diesen Export wie eingestellt zu speichern.</p><p>Laden Sie einen Export bei erneutem Bedarf über <strong>Vorlage laden</strong>.</p><h3 id="feldzuordnungsdatei-fur-serienbriefdruck" tabindex="-1">Feldzuordnungsdatei für Serienbriefdruck <a class="header-anchor" href="#feldzuordnungsdatei-fur-serienbriefdruck" aria-label="Permalink to &quot;Feldzuordnungsdatei für Serienbriefdruck&quot;">​</a></h3><p>Eine <em>Feldzuordnungsdatei</em> verändert die von SchILD verwendeten Bezeichnungen in der Kopfzeile der Exportdatei zu vom Benutzer definierten abweichenden Bezeichnern.</p>',31),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,"Es ist somit möglich, Word-Serienbriefvorlagen, die für andere Schulverwaltungssysteme erstellt wurden (z.B. IBIS) auch in SchILD weiterzuverwenden oder die Kopfzeile direkt beim Export an das von einem anderen Programm zum Import benötigte Format anzupassen.")],-1),r(`<p>Eine solche Zuordnungsdatei muss wie folgt aufgebaut sein:</p><ul><li>Die Datei beginnt zwangsläufig mit dem Text <em>[Felderzuordnung]</em></li><li>Jede für den Export ausgewählte Feldbezeichnung wird durch ein &quot;<strong>=</strong>&quot; zu einer anderen Bezeichnung. Also: <em>FeldbezeichnungSchILD=NeueBezeichnung&quot;.</em></li></ul><p>Eine Datei, um Vorname, Nachname und Geburtsdatum könnte wie folgt aussehen:</p><pre><code>[Felderzuordnung]
Nachname=SName
Vorname=SVorname
Geburtsdatum=SGebDat
</code></pre><p>Dabei wäre der von SchILD erzeugte Spaltenname <em>&quot;Nachname&quot;</em> nicht ausgegeben worden, stattdessen stünde <em>&quot;SName&quot;</em> in der Serienbriefdatei.</p><h3 id="word-seriendruck" tabindex="-1">Word Seriendruck <a class="header-anchor" href="#word-seriendruck" aria-label="Permalink to &quot;Word Seriendruck&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/verwaltung-export-6-export-word-serienbrief.png"><img src="`+g+'" alt="Anstoßen eines Word Serienbriefdrucks über den Export in Textdateien." loading="lazy"></a></p><p><em>Anstoßen eines Word Serienbriefdrucks über den Export in Textdateien.</em></p><p>Eine Exportdatei im txt-Format kann auch genutzt werden, um einen Serienbriefdruck in MS Word anzustoßen. Dies kann sinnvoll sein, da Sie Ihre schon als Word vorhandenen Vorlagen von SchILD-NRW 3 aus nutzen können.</p><p>Erstellen Sie zuerst ein Worddokument als Vorlage für den Serienbrief.</p><p>Wählen Sie für einen Serienbriefdruck die Datenart <em>Schüler</em>, dann wählen Sie alle Felder aus, die Sie im Serienbrief verwenden möchten.</p><p>Die zum Export gewählten Felder stehen in Word als Seriendruckfelder zur Verfügung.</p>',12),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Denken Sie daran, zusätzlich zu den inhaltlich benötigten Feldern alle für eine Anschrift benötigten Felder anzuwählen.")],-1),e("p",null,[n("Als Exportdatei muss die Dateiendung "),e("em",null,".txt"),n(" gewählt werden. Wurde dies getan, lässt sich nun bei "),e("strong",null,"Nach dem Export Word-Seriendruck starten"),n(" der Haken setzen. Ist die Datenart nicht "),e("em",null,"Schüler"),n(" beziehungsweise ist die Datei keine "),e("em",null,".txt"),n(", bleibt diese Option ausgegraut und nicht anwählbar.")],-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Word muss zuvor geschlossen worden sein.")],-1),r('<p>Nach einem Klick auf <strong>Export starten</strong> öffnet sich ein Fenster, in dem eine Worddatei, <em>.docx</em> anzuwählen ist. Wählen Sie Ihren Serienbrief an.</p><p>Es öffnen sich nun <em>zwei</em> Worddateien:</p><ul><li>Ihr Worddokument als Vorlage für den Serienbrief</li><li>Der generierte Serienbrief - wenn in der Vorlage noch keine Serienbrieffelder gesetzt wurden, sehen beide Dokumente identisch aus und enthalten noch keine dynamischen Informationen. Sind schon Serienbrieffelder gesetzt, wird der Serienbrief natürlich schon ausgefüllt sein.</li></ul><p><a href="/bilder/import-export-statistik/verwaltung-export-7-export-word-serienbrief-word-serienbrief.png"><img src="'+c+'" alt="Bearbeiten und generieren des Serienbriefs in Word." loading="lazy"></a></p><p><em>Bearbeiten und generieren des Serienbriefs in Word.</em></p><p>In Ihrer Word-Serienbriefvorlage steht nun ein neuer Reiter zur Verfügung. Wählen Sie <strong>Sendungen</strong> an.</p><p>Nun können über <strong>Seriendruckfeld einfügen</strong> alle von SchILD exportierten Datenfelder angewählt und in die Serienbriefvorlage eingebaut werden.</p><p>Ist der Serienbrief zufriedenstellend erstellt worden, klicken Sie auf <strong>Fertig stellen und zusammenführen</strong>, im in einem neuen Worddokument die Serienbriefe generiert zu bekommen.</p><p>Bei der Erstellung kann in Word angewählt werden, ob die Briefe direkt gedruckt, erst in Word geöffnet oder per E-Mail verschickt werden sollen. Weiterhin lässt sich der Bereich anwählen, in dem die Briefe generiert werden sollen, also <em>&quot;Alle&quot;, &quot;Den aktuellen Datensatz&quot;</em> oder einen <em>&quot;Bereich von... bis...&quot;</em>.</p><p>Beim Text- und Excel-Export stehen auch Angaben zur <strong>Klassenleitung und stellvertretenden Klassenleitung</strong> zur Verfügung. Kontrollieren Sie vor der Ausgabe Schülerauswahl, Abschnitt und gewählte Felder.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Datenexport_im_xlsx-_oder_txt-Format_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6881.</p>',12)])])}const v=i(h,[["render",m]]);export{S as __pageData,v as default};
